const body = $('Webhook').first().json.body ?? {};
const userId = $('Verify Profile Session').first().json.body.id;

const errors = [];
const updates = {};

const hasField = (field) =>
  Object.prototype.hasOwnProperty.call(body, field);

function validateNumber(field, min, max, integer = false) {
  if (!hasField(field)) return;

  const raw = body[field];

  if (
    (typeof raw !== "number" && typeof raw !== "string") ||
    (typeof raw === "string" && raw.trim() === "")
  ) {
    errors.push(`${field} must be a number.`);
    return;
  }

  const value = Number(raw);

  if (
    !Number.isFinite(value) ||
    value < min ||
    value > max ||
    (integer && !Number.isInteger(value))
  ) {
    errors.push(
      `${field} must be ${integer ? "an integer" : "a number"} between ${min} and ${max}.`
    );
    return;
  }

  updates[field] = value;
}

function validateChoice(field, allowedValues) {
  if (!hasField(field)) return;

  const value = typeof body[field] === "string"
    ? body[field].trim()
    : "";

  if (!allowedValues.includes(value)) {
    errors.push(`${field} contains an invalid value.`);
    return;
  }

  updates[field] = value;
}

function validateOptionalText(field, maxLength) {
  if (!hasField(field)) return;

  if (body[field] === null) {
    updates[field] = null;
    return;
  }

  if (typeof body[field] !== "string") {
    errors.push(`${field} must be text or null.`);
    return;
  }

  const value = body[field].trim();

  if (value.length > maxLength) {
    errors.push(`${field} must not exceed ${maxLength} characters.`);
    return;
  }

  updates[field] = value === "" ? null : value;
}

