validateNumber("height_cm", 120, 230);
validateNumber("weight_kg", 30, 250);

validateChoice("goal", [
  "fat_loss",
  "muscle_gain",
  "strength",
  "endurance",
  "general_fitness"
]);

validateChoice("experience_level", [
  "beginner",
  "intermediate",
  "advanced"
]);

validateOptionalText("injuries", 2000);
validateOptionalText("diet_preference", 1000);

if (Object.keys(updates).length === 0 && errors.length === 0) {
  errors.push("Provide at least one supported profile field to update.");
}

return [{
  json: {
    valid: errors.length === 0,
    errors,
    member_id: userId,
    updates
  }
}];

